public static String testableHtml(PageData pageData, boolean includeSuiteSetup) throws Exception {
    StringBuffer buffer = generateTestableContent(pageData, includeSuiteSetup);
    pageData.setContent(buffer.toString());
    return pageData.getHTML();
}

private static StringBuffer generateTestableContent(PageData pageData, boolean includeSuiteSetup) throws Exception {
    StringBuffer buffer = new StringBuffer();
    fetchSetupPages(pageData, buffer, includeSuiteSetup);
    buffer.append(pageData.getContent());
    fetchTeardownPages(pageData, buffer, includeSuiteSetup);
    return buffer;
}

private static void fetchSetupPages(PageData pageData, StringBuffer buffer, boolean includeSuiteSetup) throws Exception {
    if (pageData.hasAttribute("Test") && includeSuiteSetup) {
        WikiPage suiteSetup = PageCrawlerImpl.getInheritedPage(SuiteResponder.SUITE_SETUP_NAME, pageData.getWikiPage());
        if (suiteSetup != null) {
            appendIncludeStatement(suiteSetup, buffer, "setup");
        }
    }
    WikiPage setup = PageCrawlerImpl.getInheritedPage("SetUp", pageData.getWikiPage());
    if (setup != null) {
        appendIncludeStatement(setup, buffer, "setup");
    }
}

private static void fetchTeardownPages(PageData pageData, StringBuffer buffer, boolean includeSuiteSetup) throws Exception {
    if (pageData.hasAttribute("Test")) {
        WikiPage teardown = PageCrawlerImpl.getInheritedPage("TearDown", pageData.getWikiPage());
        if (teardown != null) {
            appendIncludeStatement(teardown, buffer, "teardown");
        }
        if (includeSuiteSetup) {
            WikiPage suiteTeardown = PageCrawlerImpl.getInheritedPage(SuiteResponder.SUITE_TEARDOWN_NAME, pageData.getWikiPage());
            if (suiteTeardown != null) {
                appendIncludeStatement(suiteTeardown, buffer, "teardown");
            }
        }
    }
}

private static void appendIncludeStatement(WikiPage page, StringBuffer buffer, String type) throws Exception {
    WikiPagePath pagePath = page.getPageCrawler().getFullPath(page);
    String pagePathName = PathParser.render(pagePath);
    buffer.append("!include -").append(type).append(" .").append(pagePathName).append("\n");
}
